mapper.sql:
WHERE q.deleted=0 AND c.owner_id IS NOT NULL 
    AND q.customer_id=#{customerId}
    AND q.opportunity_id=#{opportunityId}
    AND (q.quote_no LIKE CONCAT('%',#{keyword},'%') OR q.title LIKE CONCAT('%',#{keyword},'%') OR c.company_name LIKE CONCAT('%',#{keyword},'%') OR b.title LIKE CONCAT('%',#{keyword},'%'))
    AND q.status='SENT' AND q.valid_until < CURRENT_DATEAND q.status='SENT' AND q.valid_until >= CURRENT_DATEAND q.status=#{status}
    AND q.is_final=1

mapper.select:
SELECT b.*,c.company_name AS customer_name,c.owner_id,o.dept_id AS owner_dept_id,o.real_name AS owner_name FROM crm_opportunity b JOIN crm_customer c ON c.id=b.customer_id LEFT JOIN sys_user o ON o.id=c.owner_id WHERE c.owner_id IS NOT NULL AND b.stage NOT IN('WON','LOST') 
    AND b.customer_id=#{customerId}
    AND (b.title LIKE CONCAT('%',#{keyword},'%') OR c.company_name LIKE CONCAT('%',#{keyword},'%')) ORDER BY b.id DESC LIMIT 50
